import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Method,
	Prop,
	Watch,
	h,
} from "@stencil/core";
import { caretDown } from "../../../icons/index";
import { focusVisible } from "../../utils/focus-visible";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

let id = 0;

const defaultAria = {
	triggerButtonLabel: "Trigger Button",
	expandButton: "Expand Button", //deprecated, use triggerButtonLabel instead
	collapseButton: "Collapse Button", //deprecated, use triggerButtonLabel instead
};

/**
 * @since 0.0.10
 * @status stable
 *
 * @data-testid accordion--trigger - The default accordion trigger button.
 *
 * @slot - The accordions' content.
 * @slot label - The accordion's label. Alternatively, you can use the label prop.
 *
 * @part base - The component's base wrapper.
 * @part header - The label header.
 * @part label - The accordion label.
 * @part trigger - The expand/collapse trigger icon.
 * @part content - The accordion content.
 */

@Component({
	tag: "hbr-accordion",
	styleUrl: "accordion.scss",
	shadow: true,
})
export class Accordion {
	body: HTMLElement;
	componentId = `accordion-${++id}`;
	accordion: HTMLElement;
	header: HTMLElement;
	isVisible = false;
	unsubscriber;

	@Element() host: HTMLHbrAccordionElement;

	/** Indicates whether or not the accordion is open. You can use this in lieu of the show/hide methods. */
	@Prop({ mutable: true, reflect: true }) open = false;

	/** Deprecated. Use label instead */
	@Prop() summary = "";

	/** Set to true to control the accordion's state from the application / framework's side */
	@Prop({ reflect: true }) uncontrolled = false;

	/** The label to show in the accordion header. If you need to display HTML, use the `label` slot instead. */
	@Prop() label = "";

	/** The accordion's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** Set to true for preventing header from triggering the accordion open or close, if there are interactive elements rendered on the header. */
	@Prop({ reflect: true }) interactive = false;

	@Prop({}) aria = {
		triggerButtonLabel: "Trigger Button",
		expandButton: "Expand Button", //deprecated, use triggerButtonLabel instead
		collapseButton: "Collapse Button", //deprecated, use triggerButtonLabel instead
	};

	/** The accordion's type. */
	@Prop({ reflect: true }) variant:
		| "stacked"
		| "borderless"
		| "contained"
		| "card" = "stacked";

	/** Set to true to prevent the user from toggling the accordion. */
	@Prop() disabled = false;

	/** The header's icon position. */
	@Prop({ reflect: true }) triggerposition: "right" | "left" | "none" = "left";

	/** Emitted when the accordion opens. Calling `event.preventDefault()` will prevent it from being opened. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted after the accordion opens and all transitions are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted when the accordion closes. Calling `event.preventDefault()` will prevent it from being closed. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the accordion closes and all transitions are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	/** Emitted when the accordion's header is clicked */
	@Event({ eventName: "hbr-header-click" }) hbrHeaderClick: EventEmitter;

	@Watch("open")
	handleOpenChange() {
		this.body ? (this.open ? this.show() : this.hide()) : null;
	}

	connectedCallback() {
		this.handleBodyTransitionEnd = this.handleBodyTransitionEnd.bind(this);
		this.handleSummaryClick = this.handleSummaryClick.bind(this);
		this.handleSummaryKeyDown = this.handleSummaryKeyDown.bind(this);
	}

	componentDidLoad() {
		focusVisible.observe(this.accordion);

		if (this.body) {
			this.body.hidden = !this.open;
		}

		// Show on init if open
		if (this.open) {
			this.body ? this.show() : null;
		}
	}

	disconnectedCallback() {
		focusVisible.unobserve(this.accordion);
	}

	/** Shows the alert. */
	@Method()
	async show() {
		// Prevent subsequent calls to the method, whether manually or triggered by the `open` watcher
		if (this.isVisible) {
			return;
		}

		const hbrShow = this.hbrShow.emit();
		if (hbrShow.defaultPrevented) {
			this.open = false;
			return;
		}
		this.body.hidden = false;
		if (this.body.scrollHeight === 0) {
			// When the scroll height can't be measured, use auto. This prevents a borked open state when the accordion is open
			// intiially, but not immediately visible (i.e. in a tab panel).
			this.body.style.height = "auto";
			this.body.style.overflow = "visible";
		} else {
			this.body.style.height = `${this.body.scrollHeight}px`;
			this.body.style.overflow = "hidden";
		}

		this.isVisible = true;
		this.open = true;
	}

	/** Hides the alert */
	@Method()
	async hide() {
		// Prevent subsequent calls to the method, whether manually or triggered by the `open` watcher
		if (!this.isVisible) {
			return;
		}

		const hbrHide = this.hbrHide.emit();
		if (hbrHide.defaultPrevented) {
			this.open = true;
			return;
		}

		// We can't transition out of `height: auto`, so let's set it to the current height first
		this.body.style.height = `${this.body.scrollHeight}px`;
		this.body.style.overflow = "hidden";

		requestAnimationFrame(() => {
			this.body.clientWidth; // force a reflow
			this.body.style.height = "0";
		});

		this.isVisible = false;
		this.open = false;
	}

	handleBodyTransitionEnd(event: TransitionEvent) {
		const target = event.target as HTMLElement;

		// Ensure we only emit one event when the target element is no longer visible
		if (
			event.propertyName === "height" &&
			target.classList.contains("accordion__body") &&
			this.body
		) {
			this.body.style.overflow = this.open ? "visible" : "hidden";
			this.body.style.height = this.open ? "auto" : "0";
			this.open
				? this.hbrAfterShow.emit({ open: this.open })
				: this.hbrAfterHide.emit({ open: this.open });
			this.body.hidden = !this.open;
		}
	}

	handleSummaryClick() {
		if (!this.disabled) {
			if (this.uncontrolled) {
				this.hbrHeaderClick.emit({ open: !this.open });
			} else {
				this.body ? (this.open ? this.hide() : this.show()) : null;
				this.header.focus();
			}
		}
	}

	handleSummaryKeyDown(event: KeyboardEvent) {
		if (event.key === "Enter" || event.key === " ") {
			event.preventDefault();
			if (this.uncontrolled) {
				this.hbrHeaderClick.emit({ open: !this.open });
			} else {
				this.body ? (this.open ? this.hide() : this.show()) : null;
			}
		}

		if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
			event.preventDefault();
			if (this.uncontrolled) {
				this.hbrHeaderClick.emit({ open: false });
			} else {
				this.body ? this.hide() : null;
			}
		}

		if (event.key === "ArrowDown" || event.key === "ArrowRight") {
			event.preventDefault();
			if (this.uncontrolled) {
				this.hbrHeaderClick.emit({ open: true });
			} else {
				this.body ? this.show() : null;
			}
		}
	}

	render() {
		const a11y = { role: null, tabIndex: null, onClick: null, onKeyDown: null };
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		if (!this.interactive) {
			a11y.role = "button";
			a11y["aria-expanded"] = this.open ? "true" : "false";
			a11y["aria-controls"] = `${this.componentId}-content`;
			a11y["aria-disabled"] = this.disabled ? "true" : "false";
			a11y.tabIndex = 0;
			a11y.onClick = () => this.handleSummaryClick();
			a11y.onKeyDown = (event) => this.handleSummaryKeyDown(event);
		}
		return (
			<div
				ref={(el) => {
					this.accordion = el;
				}}
				part="base"
				class={{
					accordion: true,
					"accordion--open": this.open,
					"accordion--disabled": this.disabled,
					[`accordion--${this.variant}`]: true,
					[`accordion--${this.size}`]: true,
				}}
			>
				<div
					ref={(el) => {
						this.header = el;
					}}
					part="header"
					id={`${this.componentId}-header`}
					class={{
						accordion__header: true,
						[`accordion--header-${this.size}`]: true,
						accordion__header__expanded: this.open,
					}}
					{...a11y}
				>
					{this.triggerposition === "left" && (
						<span part="trigger">
							{this.interactive ? (
								<hbr-button
									class="accordion__summary-icon-button"
									onClick={this.handleSummaryClick}
									onKeyDown={this.handleSummaryKeyDown}
									variant="text"
									ariaexpanded={this.open ? "true" : "false"}
									ariacontrols={`${this.componentId}-content`}
									arialabel={
										this.aria?.triggerButtonLabel
											? this.aria?.triggerButtonLabel
											: this.open
											  ? this.aria?.collapseButton ||
												  defaultAria.collapseButton
											  : this.aria?.expandButton || defaultAria.expandButton
									}
									disabled={this.disabled}
									size="large"
									data-testid="accordion--trigger"
								>
									<hbr-icon
										asset={customSystemIcons?.["caret-down"] || caretDown}
										class="accordion__summary-icon"
									/>
								</hbr-button>
							) : (
								<hbr-icon
									asset={customSystemIcons?.["caret-down"] || caretDown}
									class="accordion__summary-icon-button"
									role="button"
									aria-label={
										this.aria?.triggerButtonLabel
											? this.aria?.triggerButtonLabel
											: this.open
											  ? this.aria?.collapseButton ||
												  defaultAria.collapseButton
											  : this.aria?.expandButton || defaultAria.expandButton
									}
								/>
							)}
						</span>
					)}

					<div
						part="label"
						class={
							this.open ? "accordion__summary active" : "accordion__summary"
						}
					>
						<slot name="label">{this.summary || this.label}</slot>
					</div>

					{this.triggerposition === "right" && (
						<span part="trigger">
							{this.interactive ? (
								<hbr-button
									class="accordion__summary-icon-button"
									onClick={this.handleSummaryClick}
									onKeyDown={this.handleSummaryKeyDown}
									variant="text"
									ariaexpanded={this.open ? "true" : "false"}
									ariacontrols={`${this.componentId}-content`}
									arialabel={
										this.aria?.triggerButtonLabel
											? this.aria?.triggerButtonLabel
											: this.open
											  ? this.aria?.collapseButton ||
												  defaultAria.collapseButton
											  : this.aria?.expandButton || defaultAria.expandButton
									}
									disabled={this.disabled}
									size="large"
									data-testid="accordion--trigger"
								>
									<hbr-icon
										asset={customSystemIcons?.["caret-down"] || caretDown}
										class="accordion__summary-icon"
									/>
								</hbr-button>
							) : (
								<hbr-icon
									asset={customSystemIcons?.["caret-down"] || caretDown}
									class="accordion__summary-icon-button"
									role="button"
									aria-label={
										this.aria?.triggerButtonLabel
											? this.aria?.triggerButtonLabel
											: this.open
											  ? this.aria?.collapseButton ||
												  defaultAria.collapseButton
											  : this.aria?.expandButton || defaultAria.expandButton
									}
								/>
							)}
						</span>
					)}
				</div>

				<div
					ref={(el) => {
						this.body = el;
					}}
					class="accordion__body"
					onTransitionEnd={this.handleBodyTransitionEnd}
				>
					<div
						part="content"
						id={`${this.componentId}-content`}
						class={{
							"accordion--content": true,
							[`accordion--content-${this.size}`]: true,
						}}
						role="region"
						aria-labelledby={`${this.componentId}-header`}
					>
						<slot />
					</div>
				</div>
			</div>
		);
	}
}
